source='''def transform(grid):
    """Extend the two center axes of every solid monochrome 3x3 block."""
    h, w = len(grid), len(grid[0])
    blocks = set()
    for r in range(h - 2):
        for c in range(w - 2):
            color = grid[r][c]
            if color and all(grid[rr][cc] == color
                             for rr in range(r, r + 3)
                             for cc in range(c, c + 3)):
                blocks.add((r + 1, c + 1, color))
    out = [row[:] for row in grid]
    lines = {}
    for r, c, color in blocks:
        for cc in range(w):
            lines.setdefault((r, cc), set()).add(color)
        for rr in range(h):
            lines.setdefault((rr, c), set()).add(color)
    for (r, c), colors in lines.items():
        out[r][c] = next(iter(colors)) if len(colors) == 1 else 0
    return out
'''
